#!/bin/sh
# Generated by `codeyam-editor editor devcontainer-setup`. Runs on creation
# (postCreateCommand) and on every start (postStartCommand), so a codespace
# stopped before creation finished is repaired the next time it starts.
# Each check does nothing when the system is already healthy.

# The base image ships python3-minimal, which has no json module; the
# CodeYam Editor's hooks import it at startup.
if ! python3 -c 'import json' > /dev/null 2>&1; then
  echo 'Installing full Python for the CodeYam Editor hooks...'
  sudo apt-get update && sudo DEBIAN_FRONTEND=noninteractive apt-get install -y python3
fi

# Chromium (scenario capture) can be downloaded without its system
# libraries when creation was interrupted; reinstall it when any is missing.
for chrome in "$HOME"/.cache/ms-playwright/chromium-*/chrome-linux*/chrome; do
  if [ -x "$chrome" ] && ldd "$chrome" 2>/dev/null | grep -q 'not found'; then
    echo 'Reinstalling the system libraries Chromium needs...'
    npx -y playwright install --with-deps chromium
    break
  fi
done

exit 0
